import assert from 'node:assert/strict';
import path from 'node:path';
import {createRequire} from 'node:module';
import {randomUUID,createHash} from 'node:crypto';
import {mkdir,readFile,writeFile} from 'node:fs/promises';

/** Real shared executor, PostgreSQL and generated files; no provider boundary. */
export async function qualifyPreviewTools({db,owner,other,repo,snapshot,build,out,check}){
 const require=createRequire(import.meta.url),{ToolService}=require(path.join(build,'tool-service.js')),{WorkspaceFiles}=require(path.join(build,'workspace.js')),{WorkspaceTools,workspaceDefinitions,hashText}=require(path.join(build,'workspace-tools.js')),{previewToolScope}=require(path.join(build,'tool-execution-scope.js')),{DraftPreviewExecution}=require(path.join(build,'draft-preview-execution.js'));
 const must=result=>{if(result.error)throw Error(result.error.message);return result.data;},sha=value=>createHash('sha256').update(value).digest('hex');
 const workspaceRoot=path.join('F:/Agentopia-Acceptance/draft-preview-tools76',path.basename(out));await mkdir(workspaceRoot,{recursive:true});const note=path.join(workspaceRoot,'note.md');await writeFile(note,'Original\n',{flag:'wx'});
 class Secrets{rows=new Map();get(key){return this.rows.get(key);}async set(key,value){this.rows.set(key,value);}}
 const files=new WorkspaceFiles(new Secrets()),[reference]=await files.add(owner,[workspaceRoot]),workspace=new WorkspaceTools(files),events=[],user={id:owner,email:'generated-preview-tools@qa.invalid',admin:true};let identity={...user};
 const tools=new ToolService(db,workspace,(_,event)=>events.push(event),async()=>identity,undefined,undefined,{authorize(current){assert(current.admin);}});
 tools.planning.definitions=async()=>{throw Error('Saved-chat planning must not handle a draft preview.');};tools.validateExecution=async()=>{throw Error('Saved-request validation must not handle a draft preview.');};tools.deliverChat=async()=>{throw Error('Saved-chat delivery must not handle a draft preview.');};
 const normalTables=['agents','agent_llm_preferences','desktop_agent_profiles','conversation_sessions','chat_messages_v2','desktop_requests','desktop_codex_threads','desktop_codex_turns','desktop_tool_calls','desktop_terminal_runs','desktop_terminal_sessions','desktop_file_operations','desktop_plans'];
 const normalized=rows=>rows.map(row=>JSON.stringify(row)).sort(),baseline={};for(const table of normalTables)baseline[table]=normalized(must(await db.from(table).select('*')));
 const execution=new DraftPreviewExecution(files,tools);
 const newCase=async(permission='ask',policy=snapshot.behavior.policy)=>{
  const state={allowed:true},input={sessionId:randomUUID(),requestId:randomUUID(),sourceAgentId:null,text:'Generated preview file execution check.',snapshot:{...snapshot,behavior:{...snapshot.behavior,policy},execution:{permission,mode:'chat',files:[reference.id]}}},context=await execution.capture(user,input,new AbortController().signal,async()=>{}),row=await repo.begin(owner,input,context),request={id:row.id,conversation_id:row.conversation_id,assistant_message_id:row.id+':assistant'},options=context.options;
  const validate=async()=>{if(!state.allowed)throw Error('The preview source or selected resource changed.');const saved=must(await db.from('desktop_preview_requests').select('status,snapshot,conversation_id').eq('id',row.id).eq('user_id',owner).single());assert.equal(saved.status,'running');assert.equal(saved.conversation_id,row.conversation_id);assert.deepEqual(saved.snapshot,row.snapshot);};
  const scope=previewToolScope({owner,request:row.id,conversation:row.conversation_id,options,policy:context.policy,definitions:context.definitions,validate:()=>execution.validate(user,row,new AbortController().signal,validate)});
  const execute=(id,name,args,signal=new AbortController().signal,thread='preview-tool-thread')=>tools.execute(user,request,{id,name,arguments:JSON.stringify(args)},options,signal,undefined,undefined,thread,scope);
  const args={reference_id:reference.id,path:'note.md'},change={...args,expected_hash:hashText('Original\n'),content:'Reviewed\n',reason:'Verify the shared preview file review.'};
  const pending=async id=>{for(let n=0;n<150;n++){const found=must(await db.from('desktop_preview_tool_calls').select('*').eq('request_id',row.id).eq('arguments->>provider_call_id',id).eq('status','awaiting_approval').maybeSingle());if(found)return found;await new Promise(resolve=>setTimeout(resolve,20));}throw Error('The preview review did not appear; inspect the retained request.');};
  const finish=()=>repo.finish(owner,row.id,'completed','Generated tool checks retained.',null);return {row,request,options,context,input,state,scope,execute,args,change,pending,finish};
 };
 await check('The real shared executor reads only selected files and enforces the unsaved policy using independent PostgreSQL receipts.',async()=>{
  const f=await newCase('ask',{...snapshot.behavior.policy,tools:['workspace.read_file']});assert.equal((await f.execute('read','read_file',f.args)).content,'Original\n');assert.match((await f.execute('forbidden','write_file',f.change)).error,/draft agent policy|not enabled/);assert.equal((await tools.list(owner,f.row.conversation_id,'agent-draft-preview')).length,1);assert.deepEqual(await tools.list(other,f.row.conversation_id,'agent-draft-preview'),[]);await f.finish();
 });
 await check('Declining a preview review, including a foreign-account decision attempt, preserves the original file and prevents a retry.',async()=>{
  const f=await newCase(),work=f.execute('denied','write_file',f.change),row=await f.pending('denied');assert.equal(await readFile(note,'utf8'),'Original\n');assert.equal(row.arguments.content,undefined);await assert.rejects(tools.decide(other,row.id,true));await tools.decide(owner,row.id,false);assert((await work).denied);assert((await f.execute('denied','write_file',f.change)).duplicate);assert.equal(await readFile(note,'utf8'),'Original\n');await f.finish();
 });
 await check('Approval applies exact preview bytes once; changed arguments or a reused tool identity are rejected, and Undo restores the original.',async()=>{
  const f=await newCase(),work=f.execute('approved','write_file',f.change),row=await f.pending('approved');await tools.decide(owner,row.id,true);assert.equal((await work).sha256,hashText('Reviewed\n'));assert.equal(await readFile(note,'utf8'),'Reviewed\n');assert((await f.execute('approved','write_file',f.change)).duplicate);assert.match((await f.execute('approved','write_file',{...f.change,content:'Changed\n'})).error,/different arguments/);assert.match((await f.execute('approved','read_file',f.args)).error,/different arguments/);await f.finish();await tools.revert(owner,row.id,'agent-draft-preview');assert.equal(await readFile(note,'utf8'),'Original\n');
 });
 await check('Racing duplicate calls produce one persisted review and one confirmed file change.',async()=>{
  const f=await newCase(),work=[f.execute('race','write_file',f.change),f.execute('race','write_file',f.change)];for(const promise of work)promise.catch(()=>{});const row=await f.pending('race');await tools.decide(owner,row.id,true);await Promise.allSettled(work);assert.equal(must(await db.from('desktop_preview_tool_calls').select('id').eq('request_id',f.row.id)).length,1);assert.equal(events.filter(event=>event.requestId===f.row.id&&event.tool?.status==='awaiting_approval').length,1);assert.equal(await readFile(note,'utf8'),'Reviewed\n');await f.finish();await tools.revert(owner,row.id,'agent-draft-preview');assert.equal(await readFile(note,'utf8'),'Original\n');
 });
 await check('Stop, account changes and source revocation prevent approved pending writes from reaching the file.',async()=>{
  for(const mode of ['stop','account','source']){const f=await newCase(),controller=new AbortController(),work=f.execute(mode,'write_file',f.change,controller.signal);work.catch(()=>{});const row=await f.pending(mode);if(mode==='stop'){controller.abort();await assert.rejects(work);}else{if(mode==='account')identity={...user,id:other};else f.state.allowed=false;await tools.decide(owner,row.id,true);assert.match((await work).error,/account changed|source or selected resource changed/);}identity={...user};assert.equal(await readFile(note,'utf8'),'Original\n');assert.equal(must(await db.from('desktop_preview_tool_calls').select('status').eq('id',row.id).single()).status,mode==='stop'?'interrupted':'failed');await f.finish();}
 });
 await check('Full access follows the automatic path; the final file commit still rechecks preview authority after preparing bytes.',async()=>{
  const f=await newCase('full');assert.equal((await f.execute('full','write_file',f.change)).sha256,hashText('Reviewed\n'));const [row]=await tools.list(owner,f.row.conversation_id,'agent-draft-preview');assert(!events.some(event=>event.requestId===f.row.id&&event.tool?.status==='awaiting_approval'));await f.finish();await tools.revert(owner,row.id,'agent-draft-preview');assert.equal(await readFile(note,'utf8'),'Original\n');
  const revoked=await newCase(),original=workspace.apply.bind(workspace);workspace.apply=(u,o,p,s,guard)=>{let calls=0;return original(u,o,p,s,async()=>{if(++calls===2)revoked.state.allowed=false;await guard();});};try{const work=revoked.execute('last-guard','write_file',revoked.change),review=await revoked.pending('last-guard');await tools.decide(owner,review.id,true);assert.match((await work).error,/source or selected resource changed/);assert.equal(await readFile(note,'utf8'),'Original\n');}finally{workspace.apply=original;}await revoked.finish();
 });
 let uncertain;
 await check('PostgreSQL binds activity to its exact preview owner/session, requires call identity and separates child-thread receipts.',async()=>{
  const f=await newCase(),base={id:randomUUID(),user_id:owner,request_id:f.row.id,conversation_id:f.row.conversation_id,assistant_message_id:f.request.assistant_message_id,name:'read_file',label:'Generated receipt constraint check',status:'completed',arguments:{provider_call_id:'constraint',provider_arguments_hash:sha('constraint')}};
  for(const patch of [{user_id:other},{conversation_id:randomUUID()},{assistant_message_id:randomUUID()},{arguments:{}},{arguments:{provider_call_id:'missing-hash'}},{arguments:{provider_call_id:'',provider_arguments_hash:sha('constraint')}},{arguments:{provider_call_id:'invalid-hash',provider_arguments_hash:'invalid'}}])assert((await db.from('desktop_preview_tool_calls').insert({...base,...patch,id:randomUUID()})).error);
  for(const mutate of [c=>{c.owner=other;},c=>{c.key=null;},c=>{c.options.permission='full';},c=>{c.references[0].id=randomUUID();},c=>{c.roots[0].inode=null;}]){const changed=structuredClone(f.context);mutate(changed);await assert.rejects(repo.begin(owner,{...f.input,sessionId:randomUUID(),requestId:randomUUID()},changed));}
  await assert.rejects(repo.begin(owner,f.input,{...f.context,inputFiles:[]}),/identifier was already used/);
  const childA=randomUUID(),childB=randomUUID();must(await db.from('desktop_preview_tool_calls').insert([{...base,id:randomUUID(),native_thread_id:childA},{...base,id:randomUUID(),native_thread_id:childB}]));assert((await db.from('desktop_preview_tool_calls').insert({...base,id:randomUUID(),native_thread_id:childA,name:'write_file'})).error);await f.finish();
  uncertain=await newCase();must(await db.from('desktop_preview_tool_calls').insert({...base,id:randomUUID(),request_id:uncertain.row.id,conversation_id:uncertain.row.conversation_id,assistant_message_id:uncertain.request.assistant_message_id,status:'running',arguments:{provider_call_id:'interrupted-previous-process',provider_arguments_hash:sha('uncertain')}}));
 });
 await check('Preview file execution creates no saved agent, ordinary chat/message, normal tool receipt, terminal, file-operation journal or plan.',async()=>{for(const table of normalTables)assert.deepEqual(normalized(must(await db.from(table).select('*'))),baseline[table],table);});
 const before=must(await db.from('desktop_preview_tool_calls').select('*').order('id'));return {workspaceRoot,receiptCount:before.length,async reopened(afterDb){const rows=must(await afterDb.from('desktop_preview_tool_calls').select('*').order('id'));for(const row of rows){const saved=before.find(old=>old.id===row.id);if(row.request_id===uncertain.row.id){assert.equal(row.status,'interrupted');assert.match(row.error,/Inspect its saved activity and files/);}else assert.deepEqual(row,saved);}assert.equal(rows.length,before.length);assert.equal(await readFile(note,'utf8'),'Original\n');}};
}
